:root {
  --bg: #1e1b2e;
  --bg-accent: #2a2540;
  --card: #ffffff;
  --text: #1f1b2e;
  --muted: #6b6580;
  --border: #e6e3ef;
  --accent: #6c5ce7;
  --accent-hover: #5a4bd1;
  --accent-pressed: #4b3dbe;
  --focus: #ffb703;
  --radius: 16px;
  --shadow: 0 20px 50px rgba(15, 10, 40, 0.35);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 20% 10%, var(--bg-accent), var(--bg) 60%);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  color: var(--text);
}

.app {
  width: 100%;
  max-width: 760px;
  background: var(--card);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 28px 28px;
}

.app-header {
  text-align: center;
  margin-bottom: 28px;
}

.app-header h1 {
  margin: 0 0 8px;
  font-size: 1.75rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
  margin-bottom: 28px;
}

.swatch {
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid var(--border);
  background: #faf9fd;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(30, 20, 60, 0.12);
}

.swatch-color {
  height: 110px;
  width: 100%;
}

.swatch-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 8px 10px;
}

.hex {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.lock-btn {
  appearance: none;
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 8px;
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1rem;
  line-height: 1;
  padding: 0;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}

.lock-btn:hover {
  background: #f1eefc;
  border-color: var(--accent);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.94);
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
}

.actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.btn-generate {
  appearance: none;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font-size: 1.05rem;
  font-weight: 600;
  padding: 14px 32px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.btn-generate:hover {
  background: var(--accent-hover);
}

.btn-generate:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

.btn-generate:active {
  background: var(--accent-pressed);
  transform: translateY(1px);
}

.hint {
  margin: 0;
  font-size: 0.9rem;
  color: var(--muted);
  text-align: center;
}

@media (max-width: 560px) {
  .app {
    padding: 24px 18px 22px;
  }
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }
  .swatch-color {
    height: 90px;
  }
}

@media (max-width: 380px) {
  .palette {
    grid-template-columns: 1fr;
  }
  .swatch-color {
    height: 70px;
  }
  .btn-generate {
    width: 100%;
  }
}

(function () {
  "use strict";

  var paletteEl = document.getElementById("palette");
  var generateBtn = document.getElementById("generate");

  // State: array of {hex, locked}
  var colors = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    var c = (1 - Math.abs(2 * l - 1)) * s;
    var x = c * (1 - Math.abs(((h / 60) % 2) - 1));
    var m = l - c / 2;
    var r = 0, g = 0, b = 0;
    if (h < 60) { r = c; g = x; b = 0; }
    else if (h < 120) { r = x; g = c; b = 0; }
    else if (h < 180) { r = 0; g = c; b = x; }
    else if (h < 240) { r = 0; g = x; b = c; }
    else if (h < 300) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }
    function toHex(v) {
      var n = Math.round((v + m) * 255);
      var s2 = n.toString(16);
      return s2.length === 1 ? "0" + s2 : s2;
    }
    return ("#" + toHex(r) + toHex(g) + toHex(b)).toUpperCase();
  }

  function randomInt(max) {
    return Math.floor(Math.random() * max);
  }

  // Generate a harmonious palette using an analogous/complementary scheme.
  function generateHarmonious() {
    var baseHue = randomInt(360);
    var scheme = randomInt(3);
    var hues = [];
    var i;
    if (scheme === 0) {
      // Analogous
      var offsets = [-40, -20, 0, 20, 40];
      for (i = 0; i < 5; i++) hues.push((baseHue + offsets[i] + 360) % 360);
    } else if (scheme === 1) {
      // Complementary split
      hues = [
        baseHue,
        (baseHue + 30) % 360,
        (baseHue + 180) % 360,
        (baseHue + 210) % 360,
        (baseHue + 150) % 360
      ];
    } else {
      // Triadic-ish spread
      hues = [
        baseHue,
        (baseHue + 120) % 360,
        (baseHue + 240) % 360,
        (baseHue + 60) % 360,
        (baseHue + 300) % 360
      ];
    }
    var result = [];
    for (i = 0; i < 5; i++) {
      var sat = 45 + randomInt(30); // 45-74
      var light = 38 + randomInt(30); // 38-67
      result.push(hslToHex(hues[i], sat, light));
    }
    return result;
  }

  function regenerate() {
    var fresh = generateHarmonious();
    for (var i = 0; i < 5; i++) {
      if (!colors[i] || !colors[i].locked) {
        colors[i] = { hex: fresh[i], locked: colors[i] ? colors[i].locked : false };
      }
    }
    render();
  }

  function toggleLock(index) {
    colors[index].locked = !colors[index].locked;
    updateSwatch(index);
  }

  function createSwatch(index) {
    var wrap = document.createElement("div");
    wrap.className = "swatch";
    wrap.dataset.index = String(index);

    var color = document.createElement("div");
    color.className = "swatch-color";
    color.setAttribute("aria-hidden", "true");

    var info = document.createElement("div");
    info.className = "swatch-info";

    var hex = document.createElement("span");
    hex.className = "hex";

    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "lock-btn";
    btn.setAttribute("aria-pressed", "false");
    btn.setAttribute("aria-label", "Lock color " + (index + 1));
    btn.textContent = "\uD83D\uDD13";
    btn.addEventListener("click", function () {
      toggleLock(index);
    });

    info.appendChild(hex);
    info.appendChild(btn);
    wrap.appendChild(color);
    wrap.appendChild(info);
    return wrap;
  }

  function updateSwatch(index) {
    var wrap = paletteEl.children[index];
    if (!wrap) return;
    var c = colors[index];
    var colorEl = wrap.querySelector(".swatch-color");
    var hexEl = wrap.querySelector(".hex");
    var btn = wrap.querySelector(".lock-btn");
    colorEl.style.backgroundColor = c.hex;
    hexEl.textContent = c.hex;
    btn.setAttribute("aria-pressed", c.locked ? "true" : "false");
    btn.setAttribute("aria-label", (c.locked ? "Unlock" : "Lock") + " color " + (index + 1) + " " + c.hex);
    btn.textContent = c.locked ? "\uD83D\uDD12" : "\uD83D\uDD13";
  }

  function render() {
    paletteEl.innerHTML = "";
    for (var i = 0; i < 5; i++) {
      paletteEl.appendChild(createSwatch(i));
      updateSwatch(i);
    }
  }

  generateBtn.addEventListener("click", regenerate);

  // Initial palette
  colors = generateHarmonious().map(function (hex) {
    return { hex: hex, locked: false };
  });
  render();
})();
